mapper.select:
SELECT msg_id, client_msg_id, conversation_id, from_user_id, to_target_id, server_time,
       content, msg_type, sequence, conversation_type
from `chat_message`
WHERE msg_id IN

    #{id}

LIMIT #{size}

SELECT
msg_id, client_msg_id, conversation_id, from_user_id, to_target_id, server_time, content,
msg_type, sequence, conversation_type
FROM chat_message
WHERE 1=1

    AND conversation_id = #{dto.conversationId}


    AND msg_type = #{dto.messageType}


    AND conversation_type = #{dto.conversationType}


    AND server_time >= FROM_UNIXTIME(#{dto.fromDate} /1000)


    AND server_time <= FROM_UNIXTIME(#{dto.toDate}/1000)

ORDER BY sequence DESC

    LIMIT #{size}
